import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("a page past the last vendor is empty but still reports the total", { tag: "@LIF-15" }, async ({ apiAs, factory }) => {
  // Arrange: a unique vendor name, so searching for it gives a total no other test can change
  const member = await apiAs("member");
  const name = uniqueName("Past End");
  await factory.vendor({ name });
  const query = { q: name, limit: 10 };
  const firstPage = await expectStatus<{ items: unknown[]; total: number }>(
    await member.get("/api/vendors", { params: { ...query, offset: 0 } }),
    200,
  );
  expect(firstPage.items.length).toBe(1);

  // Act: an offset far beyond the matching total
  const response = await member.get("/api/vendors", { params: { ...query, offset: 1000 } });

  // Assert
  const pastEnd = await expectStatus<{ items: unknown[]; total: number }>(response, 200);
  expect(pastEnd.items).toEqual([]);
  expect(pastEnd.total).toBe(firstPage.total);
});
